effect.shader:
const float TAU = 6.28318530718;

void main() {
    vec2 offset = (acScreenNorm - center) * vec2(acAspect, 1.0);

    float angle = atan(offset.y, offset.x) + radians(spin);
    float radius = max(length(offset), 0.0001);

    // O inverso do raio é o que faz o centro "sumir pra dentro" — perto
    // dele, uma variação minúscula de raio já vale uma volta inteira na
    // repetição, e é isso que lê como profundidade correndo.
    float depth = repeats / radius - (acTime * travelSpeed + travel);

    vec2 tunnelUv = vec2(fract(angle / TAU + 0.5), fract(depth));
    fragColor = texture(inputImg, tunnelUv);
}
